const token = process.env.CLOUDFLARE_API_TOKEN;
const acct = "b59e38ec6e735d414dd1cef8c4739ebd";
const kvId = "fc785caf6e58419a80204ad81ec50b7d";
const headers = { Authorization: `Bearer ${token}` };
const results = [];

for (const prefix of ["contact_", "audit_"]) {
  const listUrl = `https://api.cloudflare.com/client/v4/accounts/${acct}/storage/kv/namespaces/${kvId}/keys?prefix=${prefix}`;
  const listResp = await fetch(listUrl, { headers });
  const data = await listResp.json();
  const keys = data.result || [];

  for (const key of keys) {
    const valResp = await fetch(`https://api.cloudflare.com/client/v4/accounts/${acct}/storage/kv/namespaces/${kvId}/values/${key.name}`, { headers });
    const val = await valResp.json();

    const pbCol = prefix === "contact_" ? "contacts" : "prospects";
    const pbPayload = { ...val };
    delete pbPayload.type;
    delete pbPayload.createdAt;

    try {
      const pbResp = await fetch(`http://pocketbase:8090/api/collections/${pbCol}/records`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(pbPayload)
      });
      if (pbResp.ok) {
        await fetch(`https://api.cloudflare.com/client/v4/accounts/${acct}/storage/kv/namespaces/${kvId}/values/${key.name}`, { method: "DELETE", headers });
        results.push({ processed: key.name, collection: pbCol });
      }
    } catch (e) {
      // skip
    }
  }
}

return results;
